style.css:
@-moz-document url-prefix("https://youtube.com") {
body {
    background: url("https://c4.wallpaperflare.com/wallpaper/329/965/294/deku-izuku-midoriya-boku-no-hero-anime-picture-in-picture-hd-wallpaper-preview.jpg") no-repeat center center fixed;
    background-size: cover;
    color: #00ffcc !important;
    font-family: 'Bebas Neue', sans-serif;
    text-shadow: 0 0 8px #00ffcc;
  }

  a {
    color: #50f8ff !important;
    text-shadow: 0 0 6px #50f8ff;
  }

  header, footer {
    background-color: rgba(0, 0, 0, 0.5) !important;
    border-bottom: 1px solid #00ffcc;
  }

  button {
    background-color: #00ffcc;
    color: black;
    border-radius: 10px;
    font-weight: bold;
  }
}
